// In Kotlin Activity
import android.content.Context
import android.graphics.Bitmap
import org.tensorflow.lite.support.image.TensorImage
import org.tensorflow.lite.task.vision.classifier.ImageClassifier

fun classifyImage(context: Context, bitmap: Bitmap): Pair<String, Float> {
    val classifier = ImageClassifier.createFromFile(context, "mobilenet_v2.tflite")
    val image = TensorImage.fromBitmap(bitmap)
    val results = classifier.classify(image)
    val topResult = results.firstOrNull()
    return Pair(topResult?.label ?: "unknown", topResult?.confidence ?: 0f)
}
